INSERT INTO "sources" ("slug", "name", "type", "authorization_status", "terms_url", "notes") VALUES
  ('workday_board', 'Workday careers sites', 'job_page', 'pending_review', 'https://www.workday.com/en-us/legal/site-terms.html', 'Not collected. Each company''s careers site ({company}.wdN.myworkdayjobs.com) allows its job pages in robots.txt and lists its 100 newest jobs in a sitemap; each job page carries JobPosting markup. But Workday''s Terms of Use forbid data mining, robots and "applications that interact with our Sites without our prior written consent", and do not say whether the careers sites are among those Sites. Never its /wday/cxs/ job-search API. Workday jobs a company''s own careers page shows stay covered by career_pages. Awaiting a terms decision (or Workday''s written consent). Phase 0 review, 2026-11-19.')
